mapper.select:
SELECT r.*, t.name AS tenant_name, (SELECT COUNT(*) FROM sys_role_permission rp INNER JOIN sys_permission perm ON perm.id = rp.permission_id AND perm.is_deleted = 0 WHERE rp.role_id = r.id AND rp.is_deleted = 0 AND perm.type IN ('menu', 'button')) AS permission_count FROM sys_role r LEFT JOIN sys_tenant t ON t.id = r.tenant_id AND t.is_deleted = 0 WHERE r.is_deleted = 0
AND r.tenant_id = #{tenantId}
AND (r.name LIKE CONCAT('%', #{request.keyword}, '%') OR r.code LIKE CONCAT('%', #{request.keyword}, '%'))
AND r.data_scope = #{request.dataScope}
ORDER BY ${request.safeSortField()} ${request.safeSortOrder()}
ORDER BY r.sort ASC
